// Reads one Campaign Financial Disclosure PDF into rows, and decides how far each row can be trusted.
//
// Two kinds of page:
//   text    — the PDF has a text layer (reports generated by the county's e-filing portal). The page
//             text is exact; a language model only arranges it into rows, and every amount and name
//             it returns must be found literally in that text.
//   scanned — a photographed paper form, often handwritten. A vision model reads the image; a second
//             model reads it again independently; Tesseract supplies a third reading of anything
//             printed or typed.
// A row is marked `ok` only when its amount and name are each confirmed by a second source AND the
// form's own running total adds up. Anything else is `pending` for a person to check — the caller
// keeps pending rows out of every total.
//
// Pure helpers (amount/name confirmation, checkRows, checkTotals) are exported for the tests.

import { execFile } from "node:child_process";
import { promisify } from "node:util";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const run = promisify(execFile);
const OLLAMA_URL = (process.env.OLLAMA_URL || "http://host.docker.internal:11434").replace(/\/$/, "");
const READ_TIMEOUT = Number(process.env.LOCAL_OCR_TIMEOUT_MS || 600_000);
const MAX_PAGES = Number(process.env.LOCAL_OCR_MAX_PAGES || 60);

let tools = null;
export function toolsAvailable() {
  if (tools) return tools;
  const dirs = (process.env.PATH || "").split(path.delimiter);
  const has = (bin) => dirs.some((d) => { try { fs.accessSync(path.join(d, bin), fs.constants.X_OK); return true; } catch { return false; } });
  tools = { pdftotext: has("pdftotext"), pdftoppm: has("pdftoppm"), tesseract: has("tesseract") };
  return tools;
}

export async function renderPage(file, n, dpi = 150) {
  if (!toolsAvailable().pdftoppm) throw new Error("PDF tools are missing from this build (poppler-utils).");
  const base = path.join(os.tmpdir(), `lp-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`);
  try {
    await run("pdftoppm", ["-r", String(dpi), "-png", "-f", String(n), "-l", String(n), "-singlefile", file, base], { timeout: 60_000 });
    return fs.readFileSync(`${base}.png`);
  } finally { try { fs.unlinkSync(`${base}.png`); } catch { /* never written */ } }
}
async function pageTexts(file) {
  const { stdout } = await run("pdftotext", ["-layout", file, "-"], { timeout: 120_000, maxBuffer: 64 * 1024 * 1024 });
  const pages = stdout.split("\f");
  if (pages.length > 1 && !pages[pages.length - 1].trim()) pages.pop();
  return pages;
}
async function tesseractText(png) {
  if (!toolsAvailable().tesseract) return "";
  const f = path.join(os.tmpdir(), `lt-${process.pid}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.png`);
  try { fs.writeFileSync(f, png); const { stdout } = await run("tesseract", [f, "-", "--psm", "4"], { timeout: 120_000, maxBuffer: 16 * 1024 * 1024 }); return stdout; }
  catch { return ""; }
  finally { try { fs.unlinkSync(f); } catch { /* gone */ } }
}

// ---------- page classification ----------
export function pageType(text) {
  const t = String(text || "");
  if (/ITEMIZED\s+STATEMENT\s+OF\s+(CAMPAIGN\s+)?EXPEND/i.test(t)) return "expenditures";
  if (/ITEMIZED\s+STATEMENT\s+OF\s+(CAMPAIGN\s+)?CONTRIB|ITEMIZED\s+STATEMENT\s+OF\s+IN-?KIND|IN-?KIND\s+CONTRIBUTIONS\s+RECEIVED/i.test(t) && !/SUMMARY\s+PAGE/i.test(t)) return /IN-?KIND/i.test(t.slice(0, 400)) ? "inkind" : "contributions";
  if (/STATEMENT\s+OF\s+LOANS|LOANS\s+RECEIVED\s+THIS|ITEMIZED\s+STATEMENT\s+OF\s+LOAN/i.test(t) && !/SUMMARY/i.test(t.slice(0, 300))) return "loans";
  if (/BALANCE\s+ON\s+HAND|SUMMARY\s+PAGE|CAMPAIGN\s+FINANCIAL\s+DISCLOSURE\s+STATEMENT/i.test(t)) return "summary";
  return "other";
}
const hasMoney = (text) => [...String(text).matchAll(/\d{1,3}(?:,\d{3})*\.\d{1,2}|\$\s?\d[\d,]*/g)].some((m) => Number(m[0].replace(/[^\d.]/g, "")) > 0);

// ---------- confirmation helpers ----------
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
export function textHasAmount(text, amount) {
  const a = Math.round(Number(amount) * 100) / 100;
  if (!(a > 0)) return false;
  const int = Math.trunc(a), cents = Math.round((a - int) * 100);
  const ints = [...new Set([int.toLocaleString("en-US"), String(int)])];
  const t = String(text || "").replace(/[ \t]+/g, " ");
  return ints.some((f) => {
    const re = cents
      ? new RegExp(`(^|[^\\d,.])${esc(f)}\\.${String(cents).padStart(2, "0")}(?!\\d)`)
      : new RegExp(`(^|[^\\d,.])${esc(f)}(?!\\.\\d*[1-9])(?![\\d,])`);
    return re.test(t);
  });
}
const nameTokens = (name) => String(name || "").toUpperCase().replace(/[^A-Z0-9 ]/g, " ").split(/\s+/).filter((w) => w.length >= 3 && !["THE", "AND", "INC", "LLC", "FOR"].includes(w));
export function textHasName(text, name) {
  const toks = nameTokens(name);
  if (!toks.length) return false;
  const t = String(text || "").toUpperCase();
  return toks.every((w) => t.includes(w));
}
function editDistance(a, b) {
  const m = a.length, n = b.length;
  if (!m || !n) return m + n;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    prev = cur;
  }
  return prev[n];
}
// two independent readings of a handwritten name "agree" when they are the same after normalising, or within a small edit distance
export function namesAgree(a, b) {
  const x = nameTokens(a).sort().join(" "), y = nameTokens(b).sort().join(" ");
  if (!x || !y) return false;
  if (x === y) return true;
  return editDistance(x, y) <= Math.max(1, Math.floor(Math.min(x.length, y.length) * 0.15));
}
const near = (a, b) => Math.abs(Number(a) - Number(b)) < 0.005;
const isoDate = (s) => (typeof s === "string" && /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(Date.parse(s)) ? s : null);
const num = (v) => { const n = typeof v === "string" ? Number(v.replace(/[$,\s]/g, "")) : Number(v); return Number.isFinite(n) ? Math.round(n * 100) / 100 : null; };
const str = (v, max = 160) => { const s = typeof v === "string" ? v.replace(/\s+/g, " ").trim() : ""; return s && !/^(null|n\/a|none|unknown)$/i.test(s) ? s.slice(0, max) : null; };

function cleanRows(raw, kind, page) {
  const out = [];
  for (const r of Array.isArray(raw) ? raw.slice(0, 60) : []) {
    const amount = num(r?.amount), name = str(r?.name);
    if (!(amount > 0) || !name) continue;
    out.push({ kind: kind === "expenditures" ? "expenditure" : kind === "loans" ? "loan" : kind === "inkind" ? "inkind" : "contribution", name, amount, date: isoDate(r.date),
      address: str(r.address), city: str(r.city, 60), state: str(r.state, 2)?.toUpperCase() || null, zip: (str(r.zip, 10) || "").match(/\d{5}/)?.[0] || null,
      occupation: str(r.occupation, 80), employer: str(r.employer, 120), purpose: kind === "expenditures" ? str(r.purpose, 160) : null, page });
  }
  return out;
}

// Decide each row's standing. `evidence` differs by page kind:
//   text page:    { text }                      — the exact text layer
//   scanned page: { text (tesseract), second }  — second = rows from the independent second reader (or null)
export function checkRows(rows, { scanned, text = "", second = null, prior = null, pageTotal = null, periodStart = null, periodEnd = null }) {
  const pool = (second || []).map((r) => ({ ...r, used: false }));
  const sum = Math.round(rows.reduce((a, r) => a + r.amount, 0) * 100) / 100;
  // the form prints a running total: either this page alone, or carried forward from the page before
  const totalChecked = pageTotal != null && pageTotal > 0;
  const totalOk = totalChecked && (near(sum, pageTotal) || (prior != null && near(sum + prior, pageTotal)));
  const out = rows.map((r) => {
    const flags = [];
    let amountOk = textHasAmount(text, r.amount), nameOk = textHasName(text, r.name);
    if (scanned) {
      const hit = pool.find((p) => !p.used && near(p.amount, r.amount) && namesAgree(p.name, r.name)) || pool.find((p) => !p.used && near(p.amount, r.amount));
      if (hit) { hit.used = true; amountOk = true; if (namesAgree(hit.name, r.name)) nameOk = true; else if (!nameOk) flags.push(`readers_disagree_on_name:${hit.name}`); }
      if (!amountOk) flags.push(second ? "amount_not_confirmed" : "amount_single_reader");
      if (!nameOk && !flags.some((f) => f.startsWith("readers_disagree"))) flags.push(second ? "name_not_confirmed" : "name_single_reader");
    } else {
      if (!amountOk) flags.push("amount_not_in_text");
      if (!nameOk) flags.push("name_not_in_text");
    }
    if (totalChecked && !totalOk) flags.push("page_total_mismatch");
    if (scanned && !totalChecked) flags.push("no_page_total_to_check");
    if (!r.date) flags.push("no_date");
    else if ((periodStart && r.date < periodStart) || (periodEnd && r.date > periodEnd)) flags.push("date_outside_period");
    const blocking = flags.filter((f) => f !== "no_date" || scanned);
    const review = blocking.length ? "pending" : "ok";
    const confidence = review === "ok" ? (scanned ? 0.9 : 0.98) : Math.max(0.2, 0.7 - 0.15 * blocking.length);
    return { ...r, flags, review, confidence, source: scanned ? "ocr" : "pdf-text" };
  });
  const missed = pool.filter((p) => !p.used);
  return { rows: out, sum, totalChecked, totalOk, missed };
}

// balance last + receipts − disbursements = balance: three numbers that only agree when all were read right
export function checkTotals(t) {
  if (!t) return null;
  const v = { balanceLast: num(t.balance_last), receipts: num(t.receipts), disbursements: num(t.disbursements), balance: num(t.balance), loansOutstanding: num(t.loans_outstanding),
    itemized: num(t.itemized_contributions), unitemized: num(t.unitemized_contributions) };
  if (Object.values(v).every((x) => x == null)) return null;
  const have = v.receipts != null && v.disbursements != null && v.balance != null;
  v.adds = have ? near((v.balanceLast || 0) + v.receipts - v.disbursements, v.balance) : null;
  return v;
}

// On the form the receipts and disbursements figures sit close together, and a model can attach one to
// the wrong label or drop it. When the three it did read don't add up, try the one value that would
// make them add up — and accept it only if that exact figure is printed on the page (twice, when it
// equals another figure that is already accounted for).
const countAmount = (text, a) => { const f = Math.trunc(a).toLocaleString("en-US") + "\\." + String(Math.round((a % 1) * 100)).padStart(2, "0"); return (String(text).match(new RegExp(`(^|[^\\d,.])${f}(?!\\d)`, "g")) || []).length; };
export function repairTotals(t, text) {
  if (!t || t.adds !== false) return t;
  const last = t.balanceLast || 0;
  for (const [key, value] of [["disbursements", last + t.receipts - t.balance], ["receipts", t.balance - last + t.disbursements], ["balance", last + t.receipts - t.disbursements]]) {
    const v = Math.round(value * 100) / 100;
    if (!(v >= 0)) continue;
    const others = ["balanceLast", "receipts", "disbursements", "balance"].filter((k) => k !== key && t[k] != null && near(t[k], v)).length;
    if (v === 0 ? false : countAmount(text, v) > others) { t.repaired = { field: key, from: t[key] }; t[key] = v; t.adds = true; return t; }
  }
  return t;
}

// ---------- model calls ----------
const SCHEMA = `Return ONLY a JSON object:
{"page_type": "summary" | "contributions" | "inkind" | "loans" | "expenditures" | "other",
 "period_start": "YYYY-MM-DD" or null, "period_end": "YYYY-MM-DD" or null,
 "summary": {"balance_last": number|null, "receipts": number|null, "disbursements": number|null, "balance": number|null, "loans_outstanding": number|null, "unitemized_contributions": number|null, "itemized_contributions": number|null} or null,
 "prior_total": number|null,   // "total from preceding page", if the page prints one
 "page_total": number|null,    // the total printed at the bottom of an itemized page, if any
 "rows": [{"name": string, "address": string|null, "city": string|null, "state": string|null, "zip": string|null, "occupation": string|null, "employer": string|null, "purpose": string|null, "date": "YYYY-MM-DD"|null, "amount": number}]}
Rules: one row per filled-in contribution, loan or expenditure entry; skip blank entry blocks. For a person write "LAST, FIRST MIDDLE"; for a business or organization write its name. "name" is the contributor (or, on an expenditure page, who was paid). "amount" is the amount of that entry, not the aggregate. Copy exactly what is written; use null for anything blank or unreadable and never guess or invent. A dash, a slashed zero or an empty line means 0 or null. Rows and summary stay empty on pages that have none.`;
const TEXT_PROMPT = (text) => `Below is the text of ONE page of a Tennessee Campaign Financial Disclosure Statement, extracted from a PDF. It is a blank form with the filer's answers printed over it, so each answer usually sits on the line just ABOVE (or beside) the label or blank it belongs to, and a number may be split across two lines.\n\n${SCHEMA}\n\n--- PAGE TEXT ---\n${text.slice(0, 14000)}`;
const IMAGE_PROMPT = `This image is ONE page of a Tennessee Campaign Financial Disclosure Statement, a scanned paper form that may be filled in by hand. Read it carefully.\n\n${SCHEMA}`;

async function ask(model, prompt, image = null) {
  const body = { model, stream: false, format: "json", keep_alive: "30m", options: { temperature: 0, num_ctx: 8192 }, messages: [{ role: "user", content: prompt, ...(image ? { images: [image.toString("base64")] } : {}) }] };
  const r = await fetch(`${OLLAMA_URL}/api/chat`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body), signal: AbortSignal.timeout(READ_TIMEOUT) });
  if (!r.ok) throw new Error(`Ollama (${model}) answered HTTP ${r.status}: ${(await r.text()).slice(0, 160)}`);
  const content = (await r.json())?.message?.content || "";
  try { return JSON.parse(content); } catch { const m = content.match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch { /* fall through */ } } throw new Error(`${model} did not return JSON`); }
}

// ---------- one document ----------
export async function readDocument(file, { models, isStopped = () => false }) {
  if (!toolsAvailable().pdftotext) throw new Error("PDF tools are missing from this build (poppler-utils).");
  const texts = await pageTexts(file);
  const pages = texts.length;
  if (!pages) throw new Error("The PDF has no pages.");
  const flags = [], rows = [];
  let totals = null, periodStart = null, periodEnd = null, anyScan = false, anyText = false, prior = { contribution: null, expenditure: null };
  if (pages > MAX_PAGES) flags.push(`only the first ${MAX_PAGES} of ${pages} pages were read`);

  // Pass 1 — look at every page without a model: text layer or scan, and what kind of page it is.
  const work = [];
  for (let i = 0; i < Math.min(pages, MAX_PAGES); i++) {
    if (isStopped()) return { stopped: true };
    const layer = texts[i] || "";
    if ((layer.match(/[A-Za-z0-9]/g) || []).length > 200) {
      anyText = true;
      const type = pageType(layer);
      if (type === "other") continue;
      if (type !== "summary" && !hasMoney(layer.replace(/preceding page[^\n]*\n?[^\n]*/gi, ""))) continue; // an unused itemized page
      work.push({ i, scanned: false, text: layer, type });
    } else {
      anyScan = true;
      if (!toolsAvailable().pdftoppm) throw new Error("This is a scanned document and the image tools are missing from this build.");
      const png = await renderPage(file, i + 1, 150);
      const ocr = await tesseractText(png);
      const guess = pageType(ocr);
      if (guess === "other" && (ocr.match(/[A-Za-z]/g) || []).length > 400 && /OBLIGATION|INSTRUCTIONS/i.test(ocr)) continue; // a printed page that is clearly not an itemized schedule
      work.push({ i, scanned: true, text: ocr, png, guess });
    }
  }
  // Passes 2-4 — one model at a time across the whole document, so a large model is loaded once
  // rather than swapped in and out for every page.
  for (const w of work.filter((x) => x.scanned)) {
    if (isStopped()) return { stopped: true };
    try { w.parsed = await ask(models.vision, IMAGE_PROMPT, w.png); } catch (e) { flags.push(`page ${w.i + 1}: ${e.message}`); }
    w.type = ["summary", "contributions", "inkind", "loans", "expenditures"].includes(w.parsed?.page_type) ? w.parsed.page_type : w.guess;
  }
  for (const w of work.filter((x) => !x.scanned)) {
    if (isStopped()) return { stopped: true };
    try { w.parsed = await ask(models.text, TEXT_PROMPT(w.text)); } catch (e) { flags.push(`page ${w.i + 1}: ${e.message}`); }
  }
  if (models.verify && models.verify !== models.vision) {
    for (const w of work.filter((x) => x.scanned && x.parsed && x.type !== "other")) {
      if (isStopped()) return { stopped: true };
      try { const b = await ask(models.verify, IMAGE_PROMPT, w.png); w.second = { rows: cleanRows(b?.rows, w.type, w.i + 1), summary: b?.summary || null }; }
      catch (e) { flags.push(`page ${w.i + 1}: second reader failed (${e.message})`); }
    }
  }

  for (const w of work) {
    const { i, parsed, type } = w;
    w.png = null;
    const evidence = w.scanned ? { scanned: true, text: w.text, second: w.second?.rows ?? null, secondSummary: w.second?.summary ?? null } : { scanned: false, text: w.text };
    if (!parsed || type === "other") continue;
    const ps = isoDate(parsed.period_start), pe = isoDate(parsed.period_end);
    if (ps && pe && ps <= pe && !periodStart) { periodStart = ps; periodEnd = pe; }

    if (type === "summary" && parsed.summary) {
      const t = checkTotals(parsed.summary);
      if (t && !evidence.scanned) repairTotals(t, evidence.text);
      if (t) {
        // for a scan, each figure must also be confirmed by the second reader or by Tesseract
        if (evidence.scanned) {
          const b = checkTotals(evidence.secondSummary);
          t.confirmed = ["receipts", "disbursements", "balance"].every((k) => t[k] == null || (b && b[k] != null && near(b[k], t[k])) || textHasAmount(evidence.text, t[k]) || (t[k] === 0 && (!b || b[k] == null || b[k] === 0)));
          t.readers = b ? 2 : 1;
          if (b && !t.confirmed) t.second = { receipts: b.receipts, disbursements: b.disbursements, balance: b.balance };
        } else t.confirmed = ["receipts", "disbursements", "balance"].every((k) => t[k] == null || t[k] === 0 || textHasAmount(evidence.text, t[k]));
        t.verified = t.confirmed && t.adds !== false;
        t.source = evidence.scanned ? "ocr" : "pdf-text";
        t.page = i + 1;
        // The cover page carries the balance figures and decides whether the totals are verified; the
        // separate summary page only fills in what the cover does not state (itemized / unitemized).
        if (!totals) totals = t;
        else {
          const core = totals.balance != null ? totals : t.balance != null ? t : totals, extra = core === totals ? t : totals;
          totals = { ...core };
          for (const k of ["balanceLast", "receipts", "disbursements", "balance", "loansOutstanding"]) if (totals[k] == null && extra[k] != null) totals[k] = extra[k];
          for (const k of ["itemized", "unitemized"]) if (!totals[k] && extra[k]) totals[k] = extra[k];
        }
      }
    }
    const cleaned = cleanRows(parsed.rows, type, i + 1);
    if (type !== "summary" && cleaned.length) {
      const group = type === "expenditures" ? "expenditure" : "contribution";
      const chk = checkRows(cleaned, { ...evidence, prior: num(parsed.prior_total) ?? prior[group], pageTotal: num(parsed.page_total), periodStart, periodEnd });
      rows.push(...chk.rows);
      if (chk.totalChecked && !chk.totalOk) flags.push(`page ${i + 1}: rows add to $${chk.sum.toLocaleString()} but the page total reads $${num(parsed.page_total).toLocaleString()}`);
      if (chk.missed.length) flags.push(`page ${i + 1}: the second reader saw ${chk.missed.length} entr${chk.missed.length === 1 ? "y" : "ies"} the first did not (${chk.missed.slice(0, 3).map((m) => `${m.name} $${m.amount}`).join("; ")})`);
      if (num(parsed.page_total) != null) prior[group] = num(parsed.page_total);
    }
  }

  // the summary page states how much was itemized: compare with what was read
  const itemized = rows.filter((r) => r.kind === "contribution").reduce((a, r) => a + r.amount, 0);
  if (totals?.itemized != null && totals.itemized > 0 && !near(itemized, totals.itemized)) {
    flags.push(`itemized contributions read total $${(Math.round(itemized * 100) / 100).toLocaleString()}; the summary page says $${totals.itemized.toLocaleString()}`);
    for (const r of rows) if (r.kind === "contribution" && r.source === "ocr" && r.review === "ok") { r.review = "pending"; r.flags.push("document_total_mismatch"); r.confidence = 0.5; }
  }
  if (totals && totals.adds === false) flags.push("summary figures do not add up (balance last report + receipts − disbursements ≠ balance on hand)");
  if (totals && !totals.confirmed) flags.push(totals.second ? `the two readers disagree on the summary figures (second reading: receipts ${totals.second.receipts ?? "—"}, disbursements ${totals.second.disbursements ?? "—"}, balance ${totals.second.balance ?? "—"})` : totals.source === "ocr" ? "summary figures were read by one reader only" : "a summary figure was not found in the page text");
  return { method: anyScan ? (anyText ? "mixed" : "ocr") : "text", pages, totals, periodStart, periodEnd, rows, flags };
}
